const pick = (...names) => { for (const n of names) { try { return $(n); } catch (e) {} } throw new Error('Node not found: ' + names.join(' / ')); };
// Gate: pause, 429 wait, check interval, working hours -> last 5 published posts to check
// On a manual/test run it tells you WHY it stopped instead of stopping silently.
const s = pick('Get Settings').first().json;
const posts = pick('Get Posts').all().map(i => i.json);
const logs = pick('Get Logs').all().map(i => i.json);
const isTrue = v => String(v).trim().toUpperCase() === 'TRUE';
let manual = false;
try { manual = $execution.mode === 'test' || $execution.mode === 'manual'; } catch (e) {}
try { manual = manual || $('Manual run (test)').isExecuted === true; } catch (e) {}
const stop = why => { if (manual) throw new Error('Gate stopped: ' + why); return []; };

if (isTrue(s.paused)) return stop('paused = TRUE in Settings');
const todayUTC = DateTime.utc().toISODate();
if (logs.some(l => l.action === 'rate_limited' && String(l.time).slice(0, 10) === todayUTC)) return stop('a rate_limited (429) row exists in Logs for today (UTC)');

const tz = s.timezone || 'Asia/Kolkata';
const now = DateTime.now().setZone(tz);
const [ws, we] = String(s.work_hours || '9-18').split(/[^0-9]+/).filter(Boolean).map(Number);
if (!manual) {
  if (now.weekday > 5 || now.hour < ws || now.hour >= we) return [];
  const interval = [30, 60, 120, 240].includes(Number(s.check_interval_min)) ? Number(s.check_interval_min) : 60;
  const lastCheck = logs.filter(l => l.action === 'comments_checked').map(l => DateTime.fromISO(String(l.time))).sort((a, b) => b - a)[0];
  if (lastCheck && DateTime.now().diff(lastCheck, 'minutes').minutes < interval - 2) return [];   // check interval
}
// post URN: from post_urn, or any column (post_url, renamed header...) that contains a LinkedIn URN
const urnOf = p => { const v = Object.entries(p).find(([k, v]) => /post_?ur[nl]/i.test(k.trim()) && String(v).includes('urn:li:'))?.[1]
  || Object.values(p).find(v => /urn:li:(share|ugcPost|activity):/.test(String(v)));
  return String(v || '').trim().replace(/^.*\/update\//, '').replace(/\/$/, ''); };
const out = posts.filter(p => String(p.status).trim().toLowerCase() === 'published' && urnOf(p))
  .sort((a, b) => String(b.published_at).localeCompare(String(a.published_at)))
  .slice(0, 5).map(p => ({ json: { post_urn: urnOf(p) } }));
if (!out.length) return stop('no row in Posts with status "published" and a post_urn (columns seen: ' + Object.keys(posts[0] || {}).join(', ') + ')');
return out;

const pick = (...names) => { for (const n of names) { try { return $(n); } catch (e) {} } throw new Error('Node not found: ' + names.join(' / ')); };
// One item per top-level comment
const gates = pick('Gate & Select Posts').all();
const out = [];
$input.all().forEach((it, i) => {
  const post_urn = gates[i]?.json.post_urn;
  for (const c of (it.json.elements || [])) {
    const urn = c.commentUrn || c['$URN'] || '';
    if (!urn) continue;
    out.push({ json: { post_urn, comment_urn: urn, author: c.actor || '', text: c.message?.text || '',
                       created: c.created?.time || 0 } });
  }
});
return out;

const pick = (...names) => { for (const n of names) { try { return $(n); } catch (e) {} } throw new Error('Node not found: ' + names.join(' / ')); };
// Builds each thread (top comment + replies) and keeps only NEW comments from other people
const ORG = 'urn:li:organization:YOUR_ORG_ID';
const tops = pick('Flatten Comments').all().map(i => i.json);
const known = new Set(pick('Get Comments').all().map(i => String(i.json.id || '')));
const out = [];
$input.all().forEach((it, i) => {
  const top = tops[i];
  if (!top) return;
  const replies = (it.json.elements || []).map(c => ({
    comment_urn: c.commentUrn || c['$URN'] || '', author: c.actor || '', text: c.message?.text || '', created: c.created?.time || 0,
  })).filter(r => r.comment_urn).sort((a, b) => a.created - b.created);
  const thread = [top, ...replies];
  const threadText = thread.map(c => (c.author === ORG ? 'US (company page)' : 'Commenter') + ': ' + c.text).join('\n');
  for (const c of thread) {
    if (c.author === ORG || known.has(c.comment_urn)) continue;   // skip our own replies and already-handled comments
    out.push({ json: { id: c.comment_urn, post_urn: top.post_urn, parent_urn: top.comment_urn,
                       author: c.author, text: c.text, thread: threadText } });
  }
});
return out;

const pick = (...names) => { for (const n of names) { try { return $(n); } catch (e) {} } throw new Error('Node not found: ' + names.join(' / ')); };
// AI output -> Comments row
const src = pick('Collect New Comments').all();
return $input.all().map((it, i) => {
  const raw = String(it.json.output ?? it.json.text ?? '');
  let d = {};
  try { d = JSON.parse(raw.replace(/^\s*```(json)?/i, '').replace(/```\s*$/, '').trim()); } catch (e) { d = { category: 'needs_human', reply: '' }; }
  const cat = ['spam', 'abusive', 'needs_human', 'normal'].includes(d.category) ? d.category : 'needs_human';
  const c = src[i].json;
  const status = cat === 'normal' ? 'pending' : (cat === 'needs_human' ? 'escalated' : 'skipped');
  return { json: { id: c.id, post_urn: c.post_urn, parent_urn: c.parent_urn, author: c.author, text: c.text,
                   category: cat, status, reply_text: cat === 'normal' ? String(d.reply || '') : '',
                   created_at: DateTime.now().toISO() } };
});

const pick = (...names) => { for (const n of names) { try { return $(n); } catch (e) {} } throw new Error('Node not found: ' + names.join(' / ')); };
// Approve / Reject link clicked -> decision + random 5-30 min reply delay (1 min on manual test runs)
const c = pick('Loop Over Comments').item.json;
const s = pick('Get Settings').first().json;
const approved = String($json.query?.decision || '').toLowerCase() === 'approve';
const [mn, mx] = String(s.reply_delay || '5-30').split(/[^0-9]+/).filter(Boolean).map(Number);
let manual = false;
try { manual = $('Manual run (test)').isExecuted; } catch (e) {}
const delay = manual ? 1 : Math.floor(mn + Math.random() * (mx - mn + 1));
return { json: { ...c, approved, status: approved ? 'approved' : 'rejected', delay_min: delay } };

const pick = (...names) => { for (const n of names) { try { return $(n); } catch (e) {} } throw new Error('Node not found: ' + names.join(' / ')); };
// 201 -> replied, 429 -> stop calls today, other error -> pause everything
const c = pick('Decision').item.json;
const code = Number($json.statusCode);
if (code === 201 || code === 200) return { json: { id: c.id, status: 'replied', log_action: 'comment_replied', log_details: c.id + ' | ' + c.reply_text.slice(0, 120), pause: false } };
if (code === 429) return { json: { id: c.id, status: 'reply_failed', log_action: 'rate_limited', log_details: c.id + ' | 429 on reply', pause: false } };
return { json: { id: c.id, status: 'reply_failed', log_action: 'paused_on_error',
                 log_details: c.id + ' | HTTP ' + code + ' | ' + JSON.stringify($json.body ?? $json).slice(0, 300), pause: true } };
